package com.resumeanalyzer.security;
import com.resumeanalyzer.entity.User; import com.resumeanalyzer.exception.UnauthorizedException; import org.springframework.security.core.Authentication; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Component;
@Component public class CurrentUser { public User require(){Authentication auth=SecurityContextHolder.getContext().getAuthentication();if(auth==null||!auth.isAuthenticated()||!(auth.getPrincipal() instanceof User user))throw new UnauthorizedException("Authentication required");return user;} }
